"""Origin attribution is compared case insensitively or it is not compared at all.

is_community_signal intersects the labels an evidence list carries with community_source_set, and
community_source_set lowercases every configured lane name. So the label side has to be folded too.
Unfolded, one channel spelled two ways becomes two labels, and a collector that tagged its item
V2EX or Linux.Do stops being recognized as a community source at all: its single origin signal is
filed as a below source gap instead of being surfaced as a community pulse rumor.
"""
import lib

CFG = {"community_pulse": {"community_sources": ["v2ex", "linux.do"]}}


def test_every_origin_label_comes_back_folded():
    assert lib.evidence_origin_labels([{"source": "V2EX"}]) == {"v2ex"}
    assert lib.evidence_origin_labels([{"origin_source": " Linux.Do "}]) == {"linux.do"}


def test_one_channel_spelled_two_ways_is_one_label():
    ev = [{"origin_source": "V2EX"}, {"origin_source": "v2ex"}, {"origin": "v2ex "}]
    assert lib.evidence_origin_labels(ev) == {"v2ex"}, "one channel counted as several"


def test_a_community_item_is_recognized_whatever_case_the_collector_used():
    assert lib.is_community_signal([{"origin_source": "V2EX"}], CFG) is True
    assert lib.is_community_signal([{"source": "Linux.Do"}], CFG) is True
    assert lib.is_community_signal([{"source": "HackerNews"}], CFG) is False


def test_the_pulse_route_survives_a_capitalized_tag():
    card = {"track_matched": True, "age_hours": 4.0, "evidence": [{"origin_source": "V2EX"}]}
    assert lib.community_pulse_eligible(card, CFG) is True
